const cnpj = $fromAI('cnpj', 'CNPJ informado pelo cliente em qualquer formato');
const cnpjLimpo = cnpj.replace(/\D/g, '');

if (cnpjLimpo.length !== 14) {
  return JSON.stringify({ erro: true, mensagem: 'CNPJ inválido', digitos: cnpjLimpo.length });
}

try {
  const response = await $http.get({
    url: `https://brasilapi.com.br/api/cnpj/v1/${cnpjLimpo}`
  });
  return JSON.stringify(response.data);
} catch (e) {
  return JSON.stringify({ erro: true, mensagem: e.message });
}

const texto = ($input.item.json.texto_extraido || '').toLowerCase();

const padroes_bloqueio = [
  /ignore\s*(suas|as|todas|os)\s*instru/i,
  /esqueça\s*(suas|as|todas)\s*instru/i,
  /novo\s*prompt/i,
  /act\s*as/i,
  /you\s*are\s*now/i,
  /jailbreak/i,
  /ignore\s*previous/i,
  /system\s*prompt/i,
  /pretend\s*(you|to)/i,
  /roleplay/i,
  /finja\s*que/i,
  /finja\s*ser/i,
  /agora\s*você\s*(é|sera|vai ser)/i,
  /esqueça\s*tudo/i,
  /nova\s*instrução/i,
  /você\s*é\s*(uma|um)\s*(ia|inteligência|robô|bot|chatbot|gpt|gemini|claude|llm)/i,
  /isso\s*é\s*(um|uma)\s*(bot|ia|robô|chatbot)/i,
  /admita\s*(que|ser)/i,
  /mundiquimica\s*(é|tem|é melhor)/i,
  /mcassab\s*(é|tem|é melhor)/i,
  /anastacio\s*(é|tem|é melhor)/i,
  /citol\s*(é|tem|é melhor)/i,
  /(dps|vocês)\s*(é ruim|são ruins|não presta|péssim)/i,
  /prefiro\s*(eles|lá|outro fornecedor)/i,
  /\b(fdp|foda[\s-]?se|puta\s*que|viado|idiota|imbecil|corno|buceta|vsf)\b/i,
];

const eh_bloqueado = padroes_bloqueio.some(p => p.test(texto));

if (eh_bloqueado) {
  items[0].json['texto_extraido'] = 'olá';
  items[0].json['guardrail_ativado'] = true;
  items[0].json['guardrail_original'] = texto.substring(0, 100);
} else {
  items[0].json['guardrail_ativado'] = false;
}

return items;
